                        List<AskUrl> listUrls = db.AskUrls.ToList();
                        foreach (AskUrl qurl in listUrls)
                        {
                            writer.WriteStartElement("url");
                            writer.WriteElementString("loc", string.Format("{0}questionS/{1}", url, qurl.url));
                            writer.WriteElementString("priority", "0.5");
                            writer.WriteEndElement();
                        }
                        writer.WriteEndElement();
                        writer.WriteEndDocument();
                        writer.Flush();
                    }
                    return new HttpResponseMessage()
                    {
                        Content = new StringContent(sw.ToString(), Encoding.UTF8, "application/xml")
                    };
                }
            }
        }

